action_details.action_postfix:
// Physical nexus established - filing required
true result.ks_has_nexus xdef
"Kansas filing required: Physical presence (office, employees, or property in state)" job.audit_trail swap addto

// Economic nexus established per Wayfair - filing required
true result.ks_has_nexus xdef
"Kansas filing required: Economic nexus (exceeds $100,000 gross receipts or 200 transactions)" job.audit_trail swap addto

// Calculate Kansas state additions
0.0 /ks_additions xdef

// Common Kansas additions:
// - Federal interest income
// - State income tax refunds
// - IRC 163(j) adjustments

result.ks_us_interest_income 0.0 ne
{
  ks_additions result.ks_us_interest_income add /ks_additions xdef
} if

result.ks_state_tax_refunds 0.0 ne
{
  ks_additions result.ks_state_tax_refunds add /ks_additions xdef
} if

ks_additions result.ks_state_additions xdef

// Calculate Kansas state subtractions
0.0 /ks_subtractions xdef

// Common Kansas subtractions:
// - Kansas municipal bond interest
// - State income taxes paid
// - Kansas NOL deduction

result.ks_municipal_interest 0.0 ne
{
  ks_subtractions result.ks_municipal_interest add /ks_subtractions xdef
} if

result.ks_state_taxes_paid 0.0 ne
{
  ks_subtractions result.ks_state_taxes_paid add /ks_subtractions xdef
} if

ks_subtractions result.ks_state_subtractions xdef

"Kansas additions: $" result.ks_state_additions cvs strconcat ", subtractions: $" strconcat result.ks_state_subtractions cvs strconcat job.audit_trail swap addto

// Calculate Kansas taxable income result.ks_apportioned_income result.ks_state_additions add result.ks_state_subtractions sub 0.0 max result.ks_taxable_income xdef
// Calculate Kansas base tax: 4.0% on all income result.ks_taxable_income result.ks_corp_tax_base_rate mul result.ks_base_tax xdef
// Calculate Kansas surtax: 3.0% on income over $50,000 result.ks_taxable_income result.ks_surtax_threshold sub result.ks_corp_tax_surtax_rate mul result.ks_surtax xdef
// Total tax before credits result.ks_base_tax result.ks_surtax add /ks_tax_before_credits xdef
// Subtract Kansas state credits ks_tax_before_credits result.ks_state_credits sub 0.0 max result.ks_tax_liability xdef
// Calculate refund or amount owed result.ks_estimated_payments result.ks_tax_liability sub result.ks_refund_or_owed xdef
"Kansas taxable income: $" result.ks_taxable_income cvs strconcat job.audit_trail swap addto "Kansas base tax (4.0%): $" result.ks_base_tax cvs strconcat job.audit_trail swap addto "Kansas surtax (3.0% on excess over $50K): $" result.ks_surtax cvs strconcat job.audit_trail swap addto "Kansas tax liability: $" result.ks_tax_liability cvs strconcat job.audit_trail swap addto

// Calculate Kansas taxable income result.ks_apportioned_income result.ks_state_additions add result.ks_state_subtractions sub 0.0 max result.ks_taxable_income xdef
// Apply only base rate: 4.0% result.ks_taxable_income result.ks_corp_tax_base_rate mul result.ks_base_tax xdef
0.0 result.ks_surtax xdef
// Subtract Kansas state credits result.ks_base_tax result.ks_state_credits sub 0.0 max result.ks_tax_liability xdef
// Calculate refund or amount owed result.ks_estimated_payments result.ks_tax_liability sub result.ks_refund_or_owed xdef
"Kansas taxable income: $" result.ks_taxable_income cvs strconcat job.audit_trail swap addto "Kansas tax liability (4.0%): $" result.ks_tax_liability cvs strconcat job.audit_trail swap addto
